def test_strict_tag_advance_transitive_seals_reject_macro_drift(
    tmp_path: Path,
) -> None:
    """Both transitive consumers seal the strict tag-advance macro exactly."""

    module = load_checker()
    claim = total_gate_claim(
        module, "ProductionDurableIntentTraceRefinesProgressWitness"
    )
    assert claim.verified_kernel_source is not None
    path = ROOT_DIR / claim.verified_kernel_source
    source = path.read_text(encoding="utf-8")
    macro_name = "tag_projection_strictly_advances_body"
    expected_sha256 = (
        "3671834240e325ebfd10306320d682266254384a6e163059afbbc9b01ba1575c"
    )
    effective_expected = tuple(
        module._EFFECTIVE_LOCK_TRACE_SHARED_MACRO_SHA256.items()
    )
    progress_expected = claim.verified_kernel_shared_macro_sha256
    contract_seals = (
        (
            "effective-lock refinement",
            effective_expected,
            "enter_view_projection_gate_body",
        ),
        (
            "progress-witness refinement",
            progress_expected,
            "production_durable_intent_trace_body",
        ),
    )

    items = module.rust_macro_items(source, macro_name)
    assert len(items) == 1
    macro_source = items[0].source
    assert macro_source.count("$later.view > $previous.view") == 1
    body_mutation = source.replace(
        macro_source,
        macro_source.replace(
            "$later.view > $previous.view",
            "$later.view >= $previous.view",
            1,
        ),
        1,
    )
    assert macro_source.count(f"macro_rules! {macro_name}") == 1
    name_mutation = source.replace(
        macro_source,
        macro_source.replace(
            f"macro_rules! {macro_name}",
            f"macro_rules! {macro_name}_mutated",
            1,
        ),
        1,
    )

    for description, contract_expected, direct_parent in contract_seals:
        contract_inventory = dict(contract_expected)
        assert contract_inventory[macro_name] == expected_sha256
        assert direct_parent in contract_inventory
        parent_items = module.rust_macro_items(source, direct_parent)
        assert len(parent_items) == 1
        focused_expected = (
            (
                direct_parent,
                module._rust_item_token_sha256(parent_items[0]),
            ),
            (macro_name, expected_sha256),
        )
        payload = module._shared_macro_payload(
            source,
            path=path,
            expected=focused_expected,
            description=description,
        )
        assert {
            "name": macro_name,
            "item_token_sha256": expected_sha256,
        } in payload
        parent_source = parent_items[0].source
        invocation = f"{macro_name}!("
        assert parent_source.count(invocation) == 1
        dependency_mutation = source.replace(
            parent_source,
            parent_source.replace(
                invocation,
                "tag_projection_equal_body!(",
                1,
            ),
            1,
        )
        for mutation_name, mutated in (
            ("body", body_mutation),
            ("name", name_mutation),
            ("dependency", dependency_mutation),
        ):
            with pytest.raises(ValueError, match="shared macro"):
                module._shared_macro_payload(
                    mutated,
                    path=tmp_path / f"{mutation_name}-refinement.rs",
                    expected=focused_expected,
                    description=description,
                )


@pytest.mark.parametrize(
    ("mutation", "expected_error"),
    (
        (
            "missing_production_call",
            "(exact reviewed production item token seal|"
            "exact kernel enforcement and projection)",
        ),
        ("constant_production_kernel", "constant result"),
        ("verus_ensures_true", "exact normalized signature"),
        ("disconnected_verus_proof", "must invoke its verified kernel"),
        ("altered_verus_projection", "projection builder"),
    ),
)
def _superseded_progress_witness_legacy_builder_mutations(
    tmp_path: Path,
    mutation: str,
    expected_error: str,
) -> None:
    """The real progress-witness seam rejects five proof-disconnection classes."""

    module = load_checker()
    contract = next(
        contract
        for contract in module.CROSS_TOOL_REFINEMENT_CONTRACTS
        if contract.obligation_id == "progress-witness-production-refinement"
    )
    claim = next(
        claim
        for claim in contract.claims
        if claim.constant == "ProductionDurableIntentTraceRefinesProgressWitness"
    )
    assert claim.verified_kernel_source is not None
    paths = {
        *claim.production_sources,
        claim.verus_source,
        claim.verified_kernel_source,
        *(call_site.source for call_site in claim.production_call_sites),
        *(seal.source for seal in claim.source_item_seals),
    }
    for relative in paths:
        source = ROOT_DIR / relative
        destination = tmp_path / relative
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(source, destination)

    if mutation == "missing_production_call":
        relative = claim.production_call_sites[0].source
    elif mutation in {
        "verus_ensures_true",
        "disconnected_verus_proof",
        "altered_verus_projection",
    }:
        relative = claim.verus_source
    else:
        relative = claim.verified_kernel_source
    path = tmp_path / relative
    source = path.read_text(encoding="utf-8")

    if mutation == "missing_production_call":
        old = (
            "if !production_durable_intent_trace_refines_progress_witness_kernel(\n"
            "                    durable_intent_trace,\n"
            "                ) {\n"
            "                    return Err(ReducerError::RefinementViolation);\n"
            "                }"
        )
        new = (
            "if false {\n"
            "                    return Err(ReducerError::RefinementViolation);\n"
            "                }"
        )
        assert source.count(old) == 1
        mutated_source = source.replace(old, new, 1)
    elif mutation == "constant_production_kernel":
        kernel_items = module.rust_items(source, claim.verified_kernel)
        assert len(kernel_items) == 1
        kernel_source = kernel_items[0].source
        old = claim.verified_kernel_body.strip()
        assert kernel_source.count(old) == 1
        weakened_kernel = kernel_source.replace(old, "true", 1)
        assert source.count(kernel_source) == 1
        mutated_source = source.replace(kernel_source, weakened_kernel, 1)
    elif mutation == "verus_ensures_true":
        theorem_items = module.rust_items(source, claim.verus_theorem)
        assert len(theorem_items) == 1
        theorem_source = theorem_items[0].source
        ensures_start = theorem_source.index("\n    ensures\n")
        body_start = theorem_source.index("\n{", ensures_start)
        weakened_theorem = (
            theorem_source[:ensures_start]
            + "\n    ensures\n        true,\n"
            + theorem_source[body_start:]
        )
        assert source.count(theorem_source) == 1
        mutated_source = source.replace(theorem_source, weakened_theorem, 1)
    elif mutation == "disconnected_verus_proof":
        old = (
            "assert(production_durable_intent_trace_refines_progress_witness_kernel(\n"
            "        production_durable_intent_trace_projection(projection),\n"
            "    ));"
        )
        new = "assert(production_durable_intent_trace_body!(projection));"
        assert source.count(old) == 1
        mutated_source = source.replace(old, new, 1)
    else:
        builder_items = module.rust_items(
            source, claim.theorem_projection_builder
        )
        assert len(builder_items) == 1
        builder_source = builder_items[0].source
        old = "{\n    projection\n}"
        new = "{\n    arbitrary()\n}"
        assert builder_source.count(old) == 1
        altered_builder = builder_source.replace(old, new, 1)
        assert source.count(builder_source) == 1
        mutated_source = source.replace(builder_source, altered_builder, 1)
    path.write_text(mutated_source, encoding="utf-8")

    verus_evidence = {
        "sources": [
            {
                "path": relative,
                "sha256": module._sha256_file(tmp_path / relative),
            }
            for relative in sorted(paths)
        ]
    }
    with pytest.raises(ValueError, match=expected_error):
        module._cross_tool_claim_payload(
            claim,
            verus_evidence=verus_evidence,
            root_dir=tmp_path,
        )


def test_body_service_runtime_step_source_seal_is_canonical() -> None:
    """The body-service step seal binds both reviewed retry-latch expressions."""

    module = load_checker()
    claim = next(
        claim
        for contract in module.CROSS_TOOL_REFINEMENT_CONTRACTS
        for claim in contract.claims
        if claim.constant == "ProductionBodyServiceRefinesAsyncFairness"
    )
    step_seals = tuple(
        seal
        for seal in claim.source_item_seals
        if seal.source == "crates/iroha_core/src/sumeragi/v2_runtime.rs"
        and seal.item == "step"
    )
    assert len(step_seals) == 1
    step_seal = step_seals[0]
    assert not step_seal.item_token_sha256.startswith("PENDING")
    assert len(step_seal.required_expressions) == 2

    source = (ROOT_DIR / step_seal.source).read_text(encoding="utf-8")
    items = tuple(
        item
        for item in module.rust_items(source, step_seal.item)
        if item.brace_context == step_seal.brace_context
    )
    assert len(items) == 1
    observed_sha256 = module._rust_sealed_item_token_sha256(items[0])
    assert step_seal.item_token_sha256 == observed_sha256

    payload_claim = replace(claim, source_item_seals=(step_seal,))
    assert module._cross_tool_source_item_seal_payload(
        payload_claim,
        root_dir=ROOT_DIR,
    ) == [
        {
            "source": step_seal.source,
            "item": step_seal.item,
            "kind": step_seal.kind,
            "brace_context": [list(header) for header in step_seal.brace_context],
            "item_token_sha256": observed_sha256,
            "required_expressions": [
                module._normalized_rust_contract(expression)
                for expression in step_seal.required_expressions
            ],
        }
    ]


