def test_release_module_list_covers_every_present_module_with_theorems() -> None:
    module = load_checker()
    theorem_modules = {
        path.stem
        for path in module.FORMAL_DIR.glob("*.tla")
        if re.search(r"(?m)^THEOREM\b", module.strip_tla_comments(path.read_text()))
    }
    present_release_modules = {
        name
        for name in module.RELEASE_PROOF_MODULES
        if (module.FORMAL_DIR / f"{name}.tla").is_file()
    }
    present_non_release_modules = {
        name
        for name in module.NON_RELEASE_THEOREM_MODULES
        if (module.FORMAL_DIR / f"{name}.tla").is_file()
    }
    async_source = module.strip_tla_comments(
        (module.FORMAL_DIR / "SumeragiV2AsyncNetwork.tla").read_text()
    )
    async_theorems = tuple(
        re.findall(
            r"(?m)^[ \t]*(?:LOCAL[ \t]+)?"
            r"(?:THEOREM|LEMMA|COROLLARY|PROPOSITION)[ \t]+"
            r"([A-Za-z_][A-Za-z0-9_]*)\b",
            async_source,
        )
    )

    assert set(module.RELEASE_PROOF_MODULES).isdisjoint(
        module.NON_RELEASE_THEOREM_MODULES
    )
    assert theorem_modules == (
        present_release_modules | present_non_release_modules
    )
    for name, expected_theorems in module.NON_RELEASE_THEOREM_MODULES.items():
        source = module.strip_tla_comments(
            (module.FORMAL_DIR / f"{name}.tla").read_text()
        )
        actual_theorems = tuple(
            re.findall(
                r"(?m)^[ \t]*(?:LOCAL[ \t]+)?"
                r"(?:THEOREM|LEMMA|COROLLARY|PROPOSITION)[ \t]+"
                r"([A-Za-z_][A-Za-z0-9_]*)\b",
                source,
            )
        )
        assert actual_theorems == expected_theorems
    reviewed_async_additions = tuple(
        symbol
        for additions in (
            module._ASYNC_NETWORK_REVIEWED_LOCAL_THEOREM_ADDITIONS_AFTER.values()
        )
        for symbol in additions if symbol not in module.ASYNC_NETWORK_RELEASE_THEOREMS
    )
    reviewed_async_theorems = (
        *module.ASYNC_NETWORK_RELEASE_THEOREMS,
        *reviewed_async_additions,
    )
    assert (
        len(reviewed_async_theorems)
        == len(frozenset(reviewed_async_theorems))
        == module._ASYNC_NETWORK_REVIEWED_LOCAL_THEOREM_COUNT
    )
    assert frozenset(async_theorems) == frozenset(reviewed_async_theorems)
    assert (
        hashlib.sha256("\n".join(async_theorems).encode("utf-8")).hexdigest()
        == module._ASYNC_NETWORK_REVIEWED_LOCAL_THEOREM_ORDER_SHA256
    )


