def test_typed_rollover_handoff_hashes_every_reviewed_artifact(
    tmp_path: Path,
) -> None:
    module = load_checker()
    artifact_names = tuple(
        module._TYPED_ROLLOVER_HANDOFF_FORMAL_SOURCE_SHA256
    )
    assert len(artifact_names) == 53
    assert sum(name.endswith(".tla") for name in artifact_names) == 5
    assert sum(name.endswith(".cfg") for name in artifact_names) == 48
    assert sum(name.endswith("_bug.cfg") for name in artifact_names) == 45
    assert len(module._TYPED_ROLLOVER_MODEL_SAFETY_PROVED_THEOREMS) == 38
    assert len(module._TYPED_ROLLOVER_MODEL_SAFETY_PROOFLESS_THEOREMS) == 0
    assert len(module._TYPED_ROLLOVER_LOCAL_LIVENESS_PROOFLESS_THEOREMS) == 0
    assert (
        len(module._TYPED_ROLLOVER_MODEL_SAFETY_PROVED_THEOREMS)
        + len(module._TYPED_ROLLOVER_MODEL_SAFETY_PROOFLESS_THEOREMS)
        + len(module._TYPED_ROLLOVER_LOCAL_LIVENESS_PROOFLESS_THEOREMS)
        == 38
    )

    for index, name in enumerate(artifact_names):
        case_root = tmp_path / f"formal-{index}"
        formal_dir = copy_typed_rollover_handoff_formal_fixture(
            case_root, module
        )
        path = formal_dir / name
        path.write_bytes(path.read_bytes() + b"\n")

        errors = module._typed_rollover_handoff_formal_source_fidelity_errors(
            formal_dir, case_root
        )

        assert any(
            f"{path}: typed rollover-handoff formal source must match exact "
            "reviewed SHA-256" in error
            for error in errors
        ), (name, errors)

    runner_root = tmp_path / "runner"
    formal_dir = copy_typed_rollover_handoff_formal_fixture(
        runner_root, module
    )
    runner = (
        runner_root
        / "scripts/formal/run_sumeragi_v2_typed_rollover_handoff_mutations.sh"
    )
    runner.write_bytes(runner.read_bytes() + b"\n")

    errors = module._typed_rollover_handoff_formal_source_fidelity_errors(
        formal_dir, runner_root
    )

    assert any(
        f"{runner}: typed rollover-handoff mutation runner must match exact "
        "reviewed SHA-256" in error
        for error in errors
    ), errors


