def test_serviced_candidate_production_contract_is_complete(
    tmp_path: Path,
) -> None:
    """The aggregate checker invokes a complete passing production contract."""

    module = load_checker()
    copy_serviced_candidate_production_fixture(tmp_path)

    errors = module._serviced_candidate_production_source_fidelity_errors(
        tmp_path
    )

    assert errors == []
    assert (
        "_serviced_candidate_production_source_fidelity_errors"
        in module.validate_ledger.__code__.co_names
    )
    assert_authenticated_wal_v4_negatives(module, tmp_path)

    safety_path = (
        tmp_path / "crates/iroha_core/src/sumeragi/safety_wal.rs"
    )
    canonical_safety = safety_path.read_text(encoding="utf-8")
    selector = "let linked_before = match rustix::fs::statat("
    assert canonical_safety.count(selector) == 1
    safety_path.write_text(
        canonical_safety.replace(
            selector,
            "let linked_before = match disconnected_adjacent_statat(",
            1,
        ),
        encoding="utf-8",
    )
    errors = module._serviced_candidate_production_source_fidelity_errors(
        tmp_path
    )
    assert any(
        "require exactly one parsed bounded adjacent read function named "
        "read_bounded; found 0" in error
        for error in errors
    ), errors
    safety_path.write_text(canonical_safety, encoding="utf-8")

    for old, new, expected_error in (
        (
            "fs::create_dir_all(&parent).map_err(|source| SafetyWalError::Io {",
            "fs::create_dir(&parent).map_err(|source| SafetyWalError::Io {",
            "test-path SafetyWal recovery must bind its directory before delegating",
        ),
        (
            "let read_metadata_before = file.metadata()",
            "let read_metadata_before = fs::metadata(&path)",
            "bound SafetyWal recovery must open through its retained directory",
        ),
        (
            "if !wal_metadata_revision_unchanged(&read_metadata_before, &read_metadata_after)",
            "if wal_metadata_revision_unchanged(&read_metadata_before, &read_metadata_after)",
            "WAL recovery must reject opened-file revision drift",
        ),
        (
            "file.set_len(valid_prefix_len)\n"
            "                .and_then(|()| file.sync_data())",
            "file.set_len(valid_prefix_len)\n"
            "                .and_then(|()| file.flush())",
            "crash-tail truncation must synchronize before reopening append state",
        ),
    ):
        assert canonical_safety.count(old) == 1
        safety_path.write_text(
            canonical_safety.replace(old, new, 1),
            encoding="utf-8",
        )
        errors = module._serviced_candidate_production_source_fidelity_errors(
            tmp_path
        )
        assert any(expected_error in error for error in errors), errors
    safety_path.write_text(canonical_safety, encoding="utf-8")


