@pytest.mark.parametrize(
    "decoy",
    (
        '"{dependency}"',
        "(* {dependency} *)",
    ),
)
def test_proof_dependency_names_cannot_be_spoofed_by_identifiers_or_literals(
    decoy: str,
) -> None:
    """Proof pins ignore larger identifiers, comments, and string contents."""

    module = load_checker()
    ledger = module.load_ledger()
    target_module = "SumeragiV2ExactDecisionStageServiceClosureProofs"
    symbol = "ExactDecisionRequestAdmissionCoalescingClosesLaneRunner"
    dependency = "ExactDecisionRequestLifecycleRankDescentClosesLifecycle"
    source = (module.FORMAL_DIR / f"{target_module}.tla").read_text(
        encoding="utf-8"
    )
    replacement = (
        f"Weakened{dependency}Suffix, "
        f"{decoy.format(dependency=dependency)}"
    )
    sources = {
        target_module: mutate_tla_theorem(
            source,
            symbol,
            dependency,
            replacement,
        )
    }

    errors = module._proof_obligation_architecture_errors(
        ledger["obligations"],
        sources,
    )

    assert any(
        f"{symbol} must retain reviewed proof dependencies" in error
        and dependency in error
        for error in errors
    ), errors


def test_historical_recovery_support_accounting_is_four_proved() -> None:
    module = load_checker()
    ledger = module.load_ledger()
    target_module = "SumeragiV2HistoricalRecoveryTemporalClosureProofs"
    source = (module.FORMAL_DIR / f"{target_module}.tla").read_text(
        encoding="utf-8"
    )
    assert module.HISTORICAL_RECOVERY_PROOFLESS_SUPPORT_IDS == ()
    assert module.HISTORICAL_RECOVERY_PROVED_SUPPORT_IDS == (
        "historical-recovery-authority-acquisition",
        "historical-recovery-certificate-rank-progress",
        "historical-recovery-decision-stage-ownership",
        "historical-recovery-decision-rank-progress",
    )
    proof_marker = re.compile(r"(?m)^[ \t]*(?:BY|PROOF|OBVIOUS)\b")
    for obligation_id in module.HISTORICAL_RECOVERY_PROVED_SUPPORT_IDS:
        _, symbol = module.SUPPORT_PROOF_OBLIGATION_INVENTORY[obligation_id]
        extracted = module._top_level_theorem_body(source, symbol)
        assert extracted is not None
        assert proof_marker.search(extracted[0]) is not None

    by_id = {
        obligation["id"]: obligation for obligation in ledger["obligations"]
    }
    assert all(
        obligation_id not in by_id
        for obligation_id in module.HISTORICAL_RECOVERY_PROVED_SUPPORT_IDS
    )
    assert by_id["height-liveness"]["status"] == "tlaps_proved"
    assert module._proofless_release_theorem_errors(
        ledger["obligations"],
        {target_module: source},
    ) == []


def test_proved_historical_recovery_support_accepts_proved_consumer() -> None:
    module = load_checker()
